import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"ChatGPT Plans and Codex Access","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/codex/chatgpt-plus.md","filePath":"products/ai-coding/codex/chatgpt-plus.md","lastUpdated":1787046041000}'),n={name:"products/ai-coding/codex/chatgpt-plus.md"};function s(i,e,d,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="chatgpt-plans-and-codex-access" tabindex="-1">ChatGPT Plans and Codex Access <a class="header-anchor" href="#chatgpt-plans-and-codex-access" aria-label="Permalink to &quot;ChatGPT Plans and Codex Access&quot;">​</a></h1><blockquote><p>How Codex access is tied to a ChatGPT plan, what that gets you, and where the authoritative numbers live.</p><p>This page deliberately quotes no prices or quota figures. Those change, and a stale number in a tutorial is worse than no number. The single source of truth is the <a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">official pricing page</a>.</p></blockquote><h2 id="codex-is-included-with-a-chatgpt-plan" tabindex="-1">Codex is included with a ChatGPT plan <a class="header-anchor" href="#codex-is-included-with-a-chatgpt-plan" aria-label="Permalink to &quot;Codex is included with a ChatGPT plan&quot;">​</a></h2><p>From the official Codex landing page:</p><blockquote><p>ChatGPT Plus, Pro, Business, Edu, and Enterprise plans include Codex.</p></blockquote><p>That is the important fact for the CLI: you do not buy Codex separately, and you do not need to provision an API key for normal use. You sign in with your ChatGPT account.</p><p>The <a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">pricing page</a> also lists <strong>Free</strong> and <strong>Go</strong> as including some Codex capability. The Plus card is the one that explicitly names &quot;Codex on the web, in the CLI, in the IDE extension, and on iOS.&quot; Surfaces and limits vary by plan — read that page rather than trusting a tutorial table.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # exits 0 when saved credentials are present</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # local diagnostic report</span></span></code></pre></div><p>There is no <code>codex status</code> subcommand in the official CLI reference. For the account, model, and configuration of the <em>current session</em>, use <code>/status</code> inside the TUI.</p><h2 id="which-plan-and-why-it-matters" tabindex="-1">Which plan, and why it matters <a class="header-anchor" href="#which-plan-and-why-it-matters" aria-label="Permalink to &quot;Which plan, and why it matters&quot;">​</a></h2><p>Rather than reproduce a table that will be out of date next month, here is what actually varies between plans, so you know what to look for when you read the pricing page:</p><table tabindex="0"><thead><tr><th>What varies</th><th>Why you&#39;d care</th></tr></thead><tbody><tr><td>Included usage before limits apply</td><td>How long a heavy day of agent work lasts</td></tr><tr><td>Model access</td><td>Whether the newest or fastest models are available to you</td></tr><tr><td>Cloud execution capacity</td><td>How much you can push to <code>codex cloud</code></td></tr><tr><td>Admin and governance controls</td><td>Whether you can enforce <code>requirements.toml</code> across a team</td></tr><tr><td>Seat management</td><td>Whether the plan is per-person or per-organization</td></tr></tbody></table><p>Two concrete points that are documented and worth knowing:</p><ul><li><strong>ChatGPT Pro</strong> includes access to <code>GPT-5.3-Codex-Spark</code> as a research preview.</li><li><strong>Business, Edu, and Enterprise</strong> are the plans where managed configuration matters — see <a href="./codex-glossary.html#requirementstoml-managed-policy">requirements.toml</a> for what an administrator can pin.</li></ul><p>For anything numeric, read <a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">learn.chatgpt.com/docs/pricing</a>.</p><h2 id="watching-your-own-consumption" tabindex="-1">Watching your own consumption <a class="header-anchor" href="#watching-your-own-consumption" aria-label="Permalink to &quot;Watching your own consumption&quot;">​</a></h2><p>Codex reports usage in-session, which is more useful than checking a dashboard after the fact.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/usage              # current session</span></span>
<span class="line"><span>/usage daily</span></span>
<span class="line"><span>/usage weekly</span></span>
<span class="line"><span>/usage cumulative</span></span></code></pre></div><p><code>/status</code> shows the session&#39;s account, model, and configuration state.</p><p>Two habits keep consumption predictable:</p><p><strong>Match reasoning effort to the task.</strong> <code>model_reasoning_effort</code> runs from <code>minimal</code> through <code>xhigh</code>. High effort on a one-line rename is waste; low effort on a subtle concurrency bug is false economy.</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_reasoning_effort = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;medium&quot;</span></span></code></pre></div><p><strong>Don&#39;t carry dead context.</strong> A long session that drifted off-task spends budget re-reading history that no longer matters. <code>/clear</code> between unrelated tasks is the cheapest optimization available.</p><h2 id="where-the-api-is-separate" tabindex="-1">Where the API is separate <a class="header-anchor" href="#where-the-api-is-separate" aria-label="Permalink to &quot;Where the API is separate&quot;">​</a></h2><p>Two things are billed through the OpenAI API rather than your ChatGPT plan, and both are opt-in:</p><ul><li><strong>A custom model provider.</strong> If you configure <code>model_providers</code> to point at your own endpoint, that endpoint&#39;s billing applies.</li><li><strong>High-volume image generation.</strong> Image generation normally draws on your included limits — the documentation notes it consumes them 3 to 5 times faster than text. Setting <code>OPENAI_API_KEY</code> switches large batches to API pricing instead.</li></ul><p>Under normal CLI use with <code>codex login</code>, neither applies. If you have never set <code>OPENAI_API_KEY</code> and never touched <code>model_providers</code>, your usage is on your ChatGPT plan.</p><blockquote><p>There is no <code>api_key</code> setting in the Codex configuration reference. Authentication is <code>codex login</code>, or a provider entry with <code>env_key</code> naming an environment variable. Older guides sometimes show an <code>api_key</code> key in <code>config.toml</code>; it is not present in the current official reference.</p></blockquote><h2 id="enterprise-and-team-deployments" tabindex="-1">Enterprise and team deployments <a class="header-anchor" href="#enterprise-and-team-deployments" aria-label="Permalink to &quot;Enterprise and team deployments&quot;">​</a></h2><p>If you are rolling Codex out to a team, the relevant surface is not the plan page but the managed-policy layer:</p><table tabindex="0"><thead><tr><th>Concern</th><th>Mechanism</th></tr></thead><tbody><tr><td>Restrict which approval policies are selectable</td><td><code>allowed_approval_policies</code> in <code>requirements.toml</code></td></tr><tr><td>Restrict sandbox modes</td><td><code>allowed_sandbox_modes</code></td></tr><tr><td>Restrict web search</td><td><code>allowed_web_search_modes</code> (<code>disabled</code> is always allowed)</td></tr><tr><td>Allowlist MCP servers</td><td><code>mcp_servers</code> entries with an <code>identity</code> block</td></tr><tr><td>Pin feature flags</td><td><code>[features]</code> in <code>requirements.toml</code></td></tr><tr><td>Data residency</td><td><code>enforce_residency</code></td></tr></tbody></table><p>Managed permission-profile allowlists require <strong>Codex 0.138.0 or later</strong>. Clients on 0.137.0 and earlier silently ignore <code>allowed_permission_profiles</code> and managed <code>default_permissions</code> — a rollout that assumes enforcement without checking client versions is not enforcing anything.</p><p>See the <a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Configuration Reference</a> for the full <code>requirements.toml</code> surface.</p><h2 id="chatgpt-chat-conversation" tabindex="-1">ChatGPT Chat (conversation) <a class="header-anchor" href="#chatgpt-chat-conversation" aria-label="Permalink to &quot;ChatGPT Chat (conversation) {#chatgpt-chat-conversation}&quot;">​</a></h2><p>The Claude.ai counterpart is <strong>Chat</strong>, not a separate install. Official docs split the same app into Chat / Work / Codex (<a href="https://learn.chatgpt.com/docs/use-chatgpt" target="_blank" rel="noreferrer">Use ChatGPT</a>).</p><table tabindex="0"><thead><tr><th>Choose</th><th>When</th><th>This guide</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>Questions, brainstorms, short drafts, settling a design</td><td>This page</td></tr><tr><td><strong>Work</strong></td><td>A file someone can open and review</td><td><a href="./chatgpt-work.html">ChatGPT Work</a></td></tr><tr><td><strong>Codex</strong></td><td>Repo, diff, tests, PR</td><td><a href="./codex-ai.html">Product line</a> · <a href="./codex-cli.html">CLI</a></td></tr></tbody></table><p>Chat surfaces frontend engineers actually hit:</p><ul><li><strong>Projects</strong> — chats, files, and instructions under one topic.</li><li><strong>Voice</strong> — desktop and iOS; can talk through uploaded files and Projects.</li><li><strong>Library</strong> — reuse saved files without uploading again.</li><li><strong>Web / desktop / mobile</strong> — one account. On 2026-07-09 the standalone Codex app merged into the <a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT desktop app</a>. Every plan, including Free, can open Chat, Work, and Codex; limits still come from the pricing page.</li></ul><p>The GPT-5.6 Sol slider in Chat does <strong>not</strong> change model behavior in Work or Codex.</p><h2 id="using-chatgpt-and-codex-together" tabindex="-1">Using ChatGPT and Codex together <a class="header-anchor" href="#using-chatgpt-and-codex-together" aria-label="Permalink to &quot;Using ChatGPT and Codex together&quot;">​</a></h2><p>They are different tools with different strengths, and the pairing is genuinely useful:</p><table tabindex="0"><thead><tr><th>Task</th><th>Better in</th></tr></thead><tbody><tr><td>Thinking through an approach before any code exists</td><td>Chat</td></tr><tr><td>Comparing libraries or architectures</td><td>Chat</td></tr><tr><td>An eight-slide deck / comparison sheet / recurring agenda</td><td><a href="./chatgpt-work.html">Work</a></td></tr><tr><td>Reading and changing files in a real repository</td><td>Codex</td></tr><tr><td>Running tests and iterating until green</td><td>Codex</td></tr><tr><td>Explaining a diff to a colleague</td><td>Chat</td></tr><tr><td>Automating a task in CI</td><td>Codex (<code>codex exec</code>)</td></tr></tbody></table><p>A workflow that works: settle the design in Chat, write it down as an <code>AGENTS.md</code> entry or a task description, then hand the implementation to Codex with a verification command. The design conversation and the implementation session have very different context needs, and keeping them separate produces better output from both.</p><h2 id="atlas-officially-retired-—-do-not-document-it-as-current" tabindex="-1">Atlas: officially retired — do not document it as current <a class="header-anchor" href="#atlas-officially-retired-—-do-not-document-it-as-current" aria-label="Permalink to &quot;Atlas: officially retired — do not document it as current&quot;">​</a></h2><p>The standalone <strong>ChatGPT Atlas</strong> browser is not a rumor to hedge. Official pages already closed it:</p><ul><li><a href="https://help.openai.com/en/articles/20001371-evolving-atlas-into-chatgpt-for-browser-based-agentic-work" target="_blank" rel="noreferrer">Evolving Atlas into ChatGPT</a>: browser-based agentic work moves into ChatGPT and Codex; <strong>Atlas is scheduled to stop working on 2026-08-09</strong>.</li><li><a href="https://openai.com/index/chatgpt-for-your-most-ambitious-work/" target="_blank" rel="noreferrer">ChatGPT is now a partner for your most ambitious work</a> (2026-07-09): the Codex app merges into the new ChatGPT desktop app; “We&#39;ll begin sunsetting the standalone Atlas browser.”</li><li><a href="https://help.openai.com/en/articles/6825453-chatgpt-release-notes" target="_blank" rel="noreferrer">ChatGPT Release Notes</a>, <strong>Retiring Atlas</strong>, repeats the same stop date.</li></ul><p>Today (2026-08-18) is after that date. For browser-agent work use the desktop <strong>built-in browser</strong>, the <a href="https://learn.chatgpt.com/docs/chrome-extension" target="_blank" rel="noreferrer">Chrome extension</a>, or Work’s <strong>cloud browser</strong>. Do not cite WSJ / Reddit merger rumors; those three pages are the record.</p> Whether Atlas bookmarks / passwords can still be exported from a leftover local install after 2026-08-09 is whatever the help article currently says. This guide does not invent steps. <h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Learning Map</a> — family tree and decision tree</li><li><a href="./chatgpt-work.html">ChatGPT Work</a> — reviewable deliverables, plugins, Sites</li><li><a href="./codex-cli.html">Codex CLI</a> — installation and core features</li><li><a href="./codex-ai.html">Codex Product Line</a> — CLI, IDE, app, and cloud</li><li><a href="./codex-cookbook.html">Codex Cookbook</a> — task recipes</li><li><a href="./codex-cheatsheet.html">Codex Cheatsheet</a> — commands and config keys</li></ul><h2 id="official-sources" tabindex="-1">Official sources <a class="header-anchor" href="#official-sources" aria-label="Permalink to &quot;Official sources&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">Pricing</a> — the only authority on plans and quotas</li><li><a href="https://learn.chatgpt.com/docs/use-chatgpt" target="_blank" rel="noreferrer">Use ChatGPT</a> — Chat / Work / Codex</li><li><a href="https://learn.chatgpt.com/docs/models" target="_blank" rel="noreferrer">Models</a> — model list and reasoning effort</li><li><a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Configuration Reference</a> — <code>requirements.toml</code> and every config key</li><li><a href="https://help.openai.com/en/articles/20001371-evolving-atlas-into-chatgpt-for-browser-based-agentic-work" target="_blank" rel="noreferrer">Evolving Atlas</a></li></ul>`,52)])])}const b=t(n,[["render",s]]);export{f as __pageData,b as default};
